import { RAGSourceCitation } from '../value-objects/rag-source-citation.vo';

export interface RAGAnswerMetadata {
  model: string;
  retrievalCount: number;
  latencyMs: number;
  finishReason?: string;
}

export interface CreateRAGAnswerProps {
  answer: string;
  grounded: boolean;
  sources: readonly RAGSourceCitation[];
  metadata: RAGAnswerMetadata;
}

/**
 * Domain Aggregate / Model representing the verified response generated by the RAG pipeline.
 */
export class RAGAnswer {
  public readonly answer: string;
  public readonly grounded: boolean;
  public readonly sources: readonly RAGSourceCitation[];
  public readonly metadata: Readonly<RAGAnswerMetadata>;

  private constructor(props: CreateRAGAnswerProps) {
    this.answer = props.answer;
    this.grounded = props.grounded;
    this.sources = Object.freeze([...props.sources]);
    this.metadata = Object.freeze({ ...props.metadata });
    Object.freeze(this);
  }

  public static create(props: CreateRAGAnswerProps): RAGAnswer {
    if (typeof props.answer !== 'string') {
      throw new Error('RAGAnswer requires a valid string answer.');
    }
    return new RAGAnswer(props);
  }

  /**
   * Deterministic abstention response generated when retrieved evidence is insufficient
   * to answer the user query accurately without hallucination.
   */
  public static abstain(
    reasonMessage = 'No verified documentation was found to answer this inquiry accurately.',
    model = 'none',
    latencyMs = 0,
  ): RAGAnswer {
    return new RAGAnswer({
      answer: reasonMessage,
      grounded: false,
      sources: Object.freeze([]),
      metadata: Object.freeze({
        model,
        retrievalCount: 0,
        latencyMs,
        finishReason: 'insufficient_context',
      }),
    });
  }
}
